mkdir -p /work/model && cd /work/model
cat > lock.p <<'EOF'
// Lock service with fencing tokens. Events mirror what solution.py emits.
type tGrant   = (client: int, token: int, now: int, expiry: int);
type tRelease = (client: int, token: int, now: int);
type tWrite   = (token: int, issued: int);

event eGrant:    tGrant;
event eReleased: tRelease;
event eWriteOk:  tWrite;
event eAcquire:  (client: int, now: int);
event eRel:      (client: int, token: int, now: int);
event eWrite:    (token: int);

// Grants never overlap and tokens strictly increase.
spec LockSafety observes eGrant, eReleased {
  var lastToken: int;
  var heldUntil: int;
  var holder: int;
  start state Init {
    on eGrant do (g: tGrant) {
      assert g.token > lastToken, "token did not increase";
      assert g.now >= heldUntil || g.client == holder && g.token == lastToken,
        "granted while another lease is unexpired";
      lastToken = g.token; heldUntil = g.expiry; holder = g.client;
    }
    on eReleased do (r: tRelease) {
      assert r.token == lastToken, "released a token that is not the latest";
      heldUntil = 0;
    }
  }
}

// An accepted write uses an issued token, and never a lower one than before.
spec Fencing observes eGrant, eWriteOk {
  var issued: int;
  var maxUsed: int;
  start state Init {
    on eGrant do (g: tGrant) { if (g.token > issued) issued = g.token; }
    on eWriteOk do (w: tWrite) {
      assert w.token >= 1 && w.token <= issued, "write with unissued token accepted";
      assert w.token >= maxUsed, "stale token accepted";
      maxUsed = w.token;
    }
  }
}

machine Service {
  var ttl: int; var next: int; var holder: int; var expiry: int; var held: bool;
  var maxUsed: int;
  start state Init {
    entry (t: int) { ttl = t; next = 1; }
    on eAcquire do (a: (client: int, now: int)) {
      if (held && a.now < expiry) {
        if (holder == a.client) { announce(a.client, next - 1, a.now); }
        return;
      }
      holder = a.client; held = true; expiry = a.now + ttl;
      announce(a.client, next, a.now);
      next = next + 1;
    }
    on eRel do (r: (client: int, token: int, now: int)) {
      if (held && holder == r.client && r.token == next - 1 && r.now < expiry) {
        held = false;
        announce_release(r.client, r.token, r.now);
      }
    }
    on eWrite do (w: (token: int)) {
      if (w.token >= 1 && w.token < next && w.token >= maxUsed) {
        maxUsed = w.token;
        announce_write(w.token, next - 1);
      }
    }
  }
  fun announce(c: int, t: int, n: int) { announce eGrant, (client = c, token = t, now = n, expiry = expiry); }
  fun announce_release(c: int, t: int, n: int) { announce eReleased, (client = c, token = t, now = n); }
  fun announce_write(t: int, i: int) { announce eWriteOk, (token = t, issued = i); }
}

machine Driver {
  start state Run {
    entry {
      var s: machine; var i: int;
      s = new Service(2);
      while (i < 8) {
        if ($) { send s, eAcquire, (client = choose(3), now = choose(8)); }
        else if ($) { send s, eRel, (client = choose(3), token = choose(6), now = choose(8)); }
        else { send s, eWrite, (token = choose(7)); }
        i = i + 1;
      }
    }
  }
}
EOF
mkdir -p PTst; cat > PTst/test.p <<'EOF'
test tcLock [main = Driver]: assert LockSafety, Fencing in { Service, Driver };
EOF
